import catalogJson from "@/data/metrics-catalog.json";
import type { Persona } from "@/lib/persona";

/** Generated by pipeline/build_metrics_catalog.py from the Draft 3 sheet. Do not hand-edit the JSON. */
export type MetricRole = "Input" | "Derived" | "Constraint" | "Metadata" | "Validation";

export type MetricDef = {
  id: string;
  categoryId: string;
  name: string;
  question: string;
  definition: string;
  unit: string;
  significance: string;
  dependencies: string;
  role: MetricRole | string;
  views: Record<Persona, string>;
  source: string;
  caveats: string | null;
};

export type MetricCategory = {
  id: string;
  emoji: string;
  label: string;
  metricIds: string[];
};

type Catalog = {
  generatedAt: string;
  source: { sheet: string; tab: string; rows: number; columns: number };
  categories: MetricCategory[];
  metrics: MetricDef[];
};

export const catalog = catalogJson as Catalog;

const byId = new Map(catalog.metrics.map((m) => [m.id, m]));

export function getMetric(id: string): MetricDef | undefined {
  return byId.get(id);
}

export function metricsInCategory(categoryId: string): MetricDef[] {
  const cat = catalog.categories.find((c) => c.id === categoryId);
  return cat ? cat.metricIds.map((id) => byId.get(id)!).filter(Boolean) : [];
}
